// Real-framework E2E harness.
//
//   node tests/e2e/run.mjs [example...] [--skip-dev] [--keep]
//
// For each example in examples/: copy it to a temporary directory, install the
// package from the actual `npm pack` tarball together with the example's real
// framework dependencies, type-check (when the example has a typecheck script),
// build for production, serve the build and drive a real browser through the
// links generated by route(); then start each dev server and create, rename
// and remove a page while it runs, checking the generated module and the
// browser. Results are printed as a table and written to
// $NAMED_ROUTES_E2E_REPORT (default: <workdir>/report.json).
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import {
	cp,
	lstat,
	mkdir,
	mkdtemp,
	readFile,
	realpath,
	rename,
	rm,
	writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "playwright";
import { examples } from "./examples.mjs";
import {
	binary,
	freePort,
	npm,
	ready,
	serveStatic,
	sleep,
	start,
	stop,
	until,
} from "./lib.mjs";

const pkg = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const argv = process.argv.slice(2);
const flags = new Set(argv.filter((arg) => arg.startsWith("--")));
const selected = argv.filter((arg) => !arg.startsWith("--"));
const unknown = selected.filter(
	(name) => !examples.some((example) => example.name === name),
);
if (unknown.length)
	throw new Error(`Unknown example(s): ${unknown.join(", ")}`);
const chosen = selected.length
	? examples.filter((example) => selected.includes(example.name))
	: examples;

// The real path: on Windows %TEMP% is often an 8.3 short path
// (C:\Users\RUNNER~1\...). With it the Vue demo's useRoute() returned
// undefined (most likely vue-router loaded twice through two spellings of the
// same directory); it passed from a long path. Projects live in long paths.
const work = await realpath(
	await mkdtemp(
		join(process.env.NAMED_ROUTES_E2E_DIR ?? tmpdir(), "named-routes-e2e-"),
	),
);
const report = process.env.NAMED_ROUTES_E2E_REPORT ?? join(work, "report.json");
const manifest = JSON.parse(await readFile(join(pkg, "package.json"), "utf8"));
const results = [];
const log = (message) => console.log(`[e2e] ${message}`);
/** Dev servers can still flush files for a moment after exiting; never abort the run on cleanup. */
async function remove(path) {
	try {
		await rm(path, {
			recursive: true,
			force: true,
			maxRetries: 10,
			retryDelay: 300,
		});
	} catch (caught) {
		log(`could not remove ${path}: ${caught.message}`);
	}
}

const skipped = new Set([
	"node_modules",
	".next",
	".nuxt",
	".output",
	".svelte-kit",
	".astro",
	".react-router",
	"dist",
	"build",
	"pnpm-lock.yaml",
	"pnpm-workspace.yaml",
]);
const generated =
	/(^|[\\/])(routes\.generated\.ts|routeTree\.gen\.ts|typed-router\.d\.ts|next-env\.d\.ts|AGENTS\.md|CLAUDE\.md)$/;

async function pack() {
	const output = npm(["pack", "--json", "--pack-destination", work], pkg);
	const [{ filename }] = JSON.parse(output.slice(output.indexOf("[")));
	return join(work, basename(filename));
}

async function prepare(example, tarball) {
	const root = join(work, example.name);
	await cp(join(pkg, "examples", example.name), root, {
		recursive: true,
		filter: (source) =>
			!skipped.has(basename(source)) &&
			!generated.test(source) &&
			!source.endsWith(".tsbuildinfo"),
	});
	const packagePath = join(root, "package.json");
	const local = JSON.parse(await readFile(packagePath, "utf8"));
	assert.equal(
		local.dependencies?.["@triooo/named-routes"],
		"file:../..",
		`${example.name} must depend on the local package`,
	);
	local.dependencies["@triooo/named-routes"] = `file:${tarball}`;
	await writeFile(packagePath, `${JSON.stringify(local, null, 2)}\n`);
	npm(["install", "--no-audit", "--no-fund"], root, 900000);
	// The package must be the installed tarball, not a link to this repository.
	const installed = join(root, "node_modules/@triooo/named-routes");
	assert.equal(
		(await lstat(installed)).isSymbolicLink(),
		false,
		"package was linked instead of installed",
	);
	const version = JSON.parse(
		await readFile(join(installed, "package.json"), "utf8"),
	).version;
	assert.equal(version, manifest.version);
	return root;
}

async function serveProduction(example, root) {
	if (example.serve.static) {
		const server = await serveStatic(join(root, example.serve.static), {
			fallback: example.serve.fallback,
		});
		return { url: server.url, close: server.close, logs: () => "" };
	}
	const port = await freePort();
	const file = example.serve.file
		? join(root, example.serve.file)
		: await binary(root, example.serve.bin[0], example.serve.bin[1]);
	const child = start(
		file,
		example.serve.args(port),
		root,
		example.serve.env?.(port) ?? {},
	);
	const url = `http://127.0.0.1:${port}`;
	await ready(child, `${url}${example.home}`);
	return { url, close: () => stop(child), logs: () => child.logs };
}

async function bodyIncludes(page, text, timeout = 30000) {
	await page.waitForFunction(
		// biome-ignore lint/performance/useDomNodeTextContent: only rendered, visible text counts (textContent includes inline RSC <script> payloads)
		(expected) => document.body?.innerText.includes(expected),
		text,
		{ timeout },
	);
}

/** Clicks each generated link on the home page and checks URL and rendered content. */
async function navigate(browser, base, example) {
	const page = await browser.newPage();
	const errors = [];
	const failed = [];
	page.on("pageerror", (error) => errors.push(error.message));
	page.on("console", (message) => {
		if (message.type() === "error") errors.push(`console: ${message.text()}`);
	});
	page.on("requestfailed", (request) =>
		failed.push(`${request.url()} (${request.failure()?.errorText})`),
	);
	page.on("response", (response) => {
		if (response.status() >= 400 && !response.url().endsWith("/favicon.ico"))
			failed.push(`${response.url()} → ${response.status()}`);
	});
	/** Which step failed, where the page is and what it shows. */
	const step = async (label, action) => {
		try {
			await action();
		} catch (caught) {
			const visible = await page
				// biome-ignore lint/performance/useDomNodeTextContent: report the visible text, as the assertions do
				.evaluate(() => document.body?.innerText ?? "")
				.catch(() => "(unavailable)");
			caught.message = `${label}: ${caught.message.split("\n")[0]}\n  url: ${page.url()}\n  visible text: ${JSON.stringify(visible.slice(0, 400))}\n  browser errors: ${errors.join(" | ") || "none"}\n  failed requests: ${failed.join(" | ") || "none"}`;
			throw caught;
		}
	};
	try {
		await step("public asset URL and decoded SVG", async () => {
			await page.goto(`${base}${example.home}`, {
				waitUntil: "load",
			});

			const image = page.getByTestId("public-asset");

			const expected = `${example.home.replace(/\/$/, "")}/named-routes-probe.svg`;

			// Validate the URL generated by the asset helper.
			await image.waitFor({ state: "visible" });

			assert.equal(
				await image.getAttribute("src"),
				expected,
				"Unexpected public asset URL",
			);

			// Ensure the browser downloaded and decoded the image.
			const dimensions = await image.evaluate(async (element) => {
				if (!(element instanceof HTMLImageElement)) {
					throw new Error("Expected an HTMLImageElement");
				}

				await element.decode();

				return {
					width: element.naturalWidth,
					height: element.naturalHeight,
					complete: element.complete,
				};
			});

			// Validate the official Named Routes logo dimensions.
			assert.deepEqual(
				dimensions,
				{
					width: 64,
					height: 64,
					complete: true,
				},
				`Unexpected image dimensions: ${JSON.stringify(dimensions)}`,
			);

			// Verify the HTTP response independently of Playwright.
			const url = `${base}${expected}`;

			const response = await fetch(url, {
				method: "GET",
				cache: "no-store",
				headers: {
					Accept: "image/svg+xml",
				},
			});

			assert.equal(response.status, 200, `Asset URL: ${url}`);

			assert.match(
				response.headers.get("content-type") ?? "",
				/image\/svg\+xml/i,
				"Unexpected asset MIME type",
			);

			const assetBytes = Buffer.from(await response.clone().arrayBuffer());
			const body = await response.text();
			// Generated examples opt into the asset manifest. Keep the manual example unversioned.
			if (example.name !== "react") {
				const versioned = await image.getAttribute("data-versioned-src");
				const hash = createHash("sha256")
					.update(assetBytes)
					.digest("hex")
					.slice(0, 12);
				assert.equal(
					versioned,
					`${expected}?v=${hash}`,
					"Asset version must reflect the served content",
				);
				const versionedResponse = await fetch(`${base}${versioned}`, {
					cache: "no-store",
				});
				assert.equal(versionedResponse.status, 200);
				assert.deepEqual(
					Buffer.from(await versionedResponse.arrayBuffer()),
					assetBytes,
				);
			}

			assert.ok(body.length > 0, `Empty SVG response: ${url}`);

			// Validate the SVG document.
			assert.match(
				body,
				/<svg\b/i,
				`Invalid SVG: ${JSON.stringify(body.slice(0, 500))}`,
			);

			// Validate the official Named Routes brand identity.
			assert.match(
				body,
				/<title>\s*NamedRoutes by triooo\s*<\/title>/i,
				"Missing Named Routes logo title",
			);

			assert.match(
				body,
				/viewBox=["']0 0 64 64["']/i,
				"Unexpected SVG viewBox",
			);

			// Validate the official brand colors.
			for (const color of ["#161616", "#f2f2ee", "#d5f43b"]) {
				assert.ok(
					body.toLowerCase().includes(color),
					`Missing brand color: ${color}`,
				);
			}
		});

		for (const link of example.links)
			await step(`click ${link.href} → "${link.text}"`, async () => {
				await page.goto(`${base}${example.home}`, { waitUntil: "load" });
				const anchor = page.locator(`a[href="${link.href}"]`).first();
				await anchor.waitFor({ timeout: 30000 });
				await anchor.click();
				await page.waitForURL(
					(url) => `${url.pathname}${url.search}` === link.href,
					{ timeout: 30000 },
				);
				await bodyIncludes(page, link.text);
			});
		// Direct loads of the same URLs (SSR / static output / SPA fallback).
		for (const link of example.links)
			await step(`load ${link.href} → "${link.text}"`, async () => {
				await page.goto(`${base}${link.href}`, { waitUntil: "load" });
				await bodyIncludes(page, link.text);
			});
		assert.deepEqual(
			errors,
			[],
			`Uncaught browser errors: ${errors.join("; ")}`,
		);
	} finally {
		await page.close();
	}
}

async function hasName(root, example, name) {
	return (await readFile(join(root, example.output), "utf8")).includes(
		`[${JSON.stringify(name)}]`,
	);
}

/** Creates, renames and removes a page while the dev server runs. */
async function live(browser, root, example, dev) {
	const port = await freePort();
	const file = await binary(root, dev.bin[0], dev.bin[1]);
	const child = start(file, dev.args(port), root);
	const base = `http://127.0.0.1:${port}`;
	const page = await browser.newPage();
	const visit = async (path, text) =>
		until(
			async () => {
				await page.goto(`${base}${path}`, {
					waitUntil: "load",
					timeout: 60000,
				});
				await bodyIncludes(page, text, 5000);
				return true;
			},
			`${dev.label}: ${path} did not render "${text}"`,
			90000,
		);
	try {
		await ready(child, `${base}${example.home}`);
		await visit(example.links[0].href, example.links[0].text);
		const spec = example.live;
		// Let the dev server's own watcher finish its initial crawl.
		await sleep(1500);
		await mkdir(dirname(join(root, spec.create.file)), { recursive: true });
		await writeFile(join(root, spec.create.file), spec.create.content);
		await until(
			() => hasName(root, example, spec.name),
			`${dev.label}: ${spec.name} was not discovered`,
		);
		await visit(spec.url, "Automatic settings");
		await rename(join(root, spec.rename.from), join(root, spec.rename.to));
		await writeFile(
			join(root, spec.rename.file ?? spec.rename.to),
			spec.rename.content,
		);
		await until(
			async () =>
				(await hasName(root, example, spec.renamed)) &&
				!(await hasName(root, example, spec.name)),
			`${dev.label}: rename to ${spec.renamed} was not reflected`,
		);
		await visit(spec.renamedUrl, "Automatic preferences");
		await rm(join(root, spec.remove), { recursive: true, force: true });
		await until(
			async () => !(await hasName(root, example, spec.renamed)),
			`${dev.label}: removed page stayed in the module`,
		);
	} catch (caught) {
		caught.message += `\n--- ${dev.label} logs ---\n${child.logs.slice(-6000)}`;
		throw caught;
	} finally {
		await page.close();
		await stop(child);
	}
}

const browser = await chromium.launch();
let tarball;
try {
	log(`work directory ${work}`);
	tarball = await pack();
	log(`packed ${basename(tarball)}`);
	for (const example of chosen) {
		const result = {
			example: example.label,
			build: "NOT RUN",
			typecheck: example.typecheck ? "NOT RUN" : "N/A",
			integration: "NOT RUN",
			e2e: "NOT RUN",
			notes: [],
		};
		results.push(result);
		let root;
		let server;
		const step = async (key, action) => {
			try {
				await action();
				result[key] = "PASS";
			} catch (caught) {
				result[key] = "FAIL";
				result.notes.push(`${key}: ${caught.message.slice(0, 4000)}`);
				throw caught;
			}
		};
		try {
			log(`${example.name}: installing tarball and framework dependencies`);
			await step("build", async () => {
				root = await prepare(example, tarball);
			});
			result.build = "NOT RUN";
			if (example.typecheck)
				await step("typecheck", () => npm(["run", "typecheck"], root));
			await step("build", async () => {
				npm(["run", "build"], root);
				for (const name of example.absentNames ?? [])
					assert.equal(
						await hasName(root, example, name),
						false,
						`${name} must not be a route`,
					);
			});
			await step("e2e", async () => {
				server = await serveProduction(example, root);
				await navigate(browser, server.url, example);
				if (example.missing) {
					const response = await fetch(`${server.url}${example.missing}`);
					assert.equal(
						response.status,
						404,
						`${example.missing} should be 404`,
					);
				}
				await server.close();
				server = undefined;
			});
			if (!example.live || flags.has("--skip-dev"))
				result.integration = example.live ? "NOT RUN" : "N/A";
			else
				await step("integration", async () => {
					for (const dev of example.dev) {
						log(`${example.name}: ${dev.label} live discovery`);
						await live(browser, root, example, dev);
					}
				});
			log(`${example.name}: done`);
		} catch (caught) {
			log(`${example.name}: FAILED ${caught.message.split("\n")[0]}`);
		} finally {
			await server?.close();
			if (!flags.has("--keep")) await remove(join(work, example.name));
		}
	}
} finally {
	await browser.close();
	await writeFile(
		report,
		`${JSON.stringify({ package: `${manifest.name}@${manifest.version}`, node: process.version, platform: `${process.platform}-${process.arch}`, results }, null, 2)}\n`,
	);
	console.log(
		`\n| Example | Build | Typecheck | Integration (dev) | E2E (browser) |\n|---|---|---|---|---|`,
	);
	for (const r of results)
		console.log(
			`| ${r.example} | ${r.build} | ${r.typecheck} | ${r.integration} | ${r.e2e} |`,
		);
	console.log(`\nReport: ${report}`);
	for (const r of results)
		for (const note of r.notes) console.log(`\n[${r.example}] ${note}`);
	if (!flags.has("--keep"))
		await remove(join(work, basename(tarball ?? "none")));
}
if (
	results.some((r) => Object.values(r).includes("FAIL")) ||
	results.length !== chosen.length
)
	process.exitCode = 1;
